// Normalise the two entry paths into one shape. Everything downstream reads THIS node.
// A scheduled run carries no Telegram message, so it falls back to the Config values.
const j = $input.first().json;
const msg = j.message || j.edited_message || {};
const asked = String(msg.text || msg.caption || '').trim();
const chat_id = String((msg.chat && msg.chat.id) || j.admin_chat_id || '').trim();
if (!chat_id) {
  throw new Error('No chat id. Send the workflow a Telegram message, or set admin_chat_id in the Config node for scheduled runs.');
}
return [{ json: {
  action: 'invoke',
  text: asked || String(j.default_request || 'screen US companies by revenue growth'),
  reply_text: '',
  ref: '',
  chat_id,
  language: String(j.default_language || 'en'),
  // Config acts as the floor; anything the model parses out of the request wins later.
  min_quarterly_revenue_musd: Number(j.min_quarterly_revenue_musd || 200),
  max_growth_pct: Number(j.max_growth_pct || 300),
  count: Number(j.default_count || 8)
} }];

// A Telegram send outputs the Telegram API response, not its input (rule 18), so the
// real payload has to be picked back up from the node before the progress ack.
// The ack is in SERIES rather than forked: n8n gives forked terminal nodes no ordering
// guarantee, and a measured case in the original build ran 131 seconds late.
const items = $('Prep Screen Input').all();
if (!items.length) throw new Error('Restore Ctx: Prep Screen Input produced no items');
return items.map(i => ({ json: i.json }));

const ctx = $input.first().json;

// SEC XBRL frames only reach full coverage roughly three months after a quarter
// closes. Measured 7 Oct 2026: CY2026Q3 held 20 rows, CY2026Q2 held 2303.
// These frames used to be hardcoded (CY2026Q1 vs CY2025Q1), which meant the screen
// silently compared the same stale quarter forever, so this resolves them per run.
const MIN_AGE_DAYS = 95;
const now = Date.now();
const d = new Date();
let y = d.getUTCFullYear();
let q = Math.floor(d.getUTCMonth() / 3) + 1;
let found = null;
for (let i = 0; i < 8; i++) {
  const endMs = Date.UTC(y, q * 3, 0);          // day 0 of the next month = last day of the quarter
  if ((now - endMs) / 86400000 >= MIN_AGE_DAYS) { found = { y, q }; break; }
  q -= 1;
  if (q === 0) { q = 4; y -= 1; }
}
if (!found) throw new Error('Could not resolve a settled SEC reporting quarter.');

return [{ json: {
  ...ctx,
  frame_current: 'CY' + found.y + 'Q' + found.q,
  frame_prior: 'CY' + (found.y - 1) + 'Q' + found.q
} }];

// Join three SEC datasets into a screenable universe.
// These three fetches are wired IN SERIES upstream, not as parallel siblings: n8n
// gives no ordering guarantee between siblings and $('Node').all() on a node that
// has not run yet returns [] silently.
// An OpenAI node outputs the model RESPONSE, it does not pass its input through.
// Reading $('Parse Criteria') alone lost chat_id AND silently discarded every
// criterion the model produced, so the hardcoded defaults were doing the work.
const inp = $('Prep Screen Input').first().json;
const rawCrit = $('Parse Criteria').first().json.message?.content ?? $('Parse Criteria').first().json;
let crit = {};
try { crit = typeof rawCrit === 'string' ? JSON.parse(rawCrit) : (rawCrit || {}); } catch (e) { crit = {}; }
const ctx = { ...inp, ...crit, language: crit.language || inp.language || 'en' };
if (!ctx.chat_id) throw new Error('chat_id missing: the screen context did not reach Build Candidates.');
const cur  = ($('Fetch Revenue Current').first().json.data) || [];
const prev = ($('Fetch Revenue Prior').first().json.data) || [];
const tk   = $('Fetch Ticker Map').first().json || {};

const cik2 = {};
for (const k of Object.keys(tk)) {
  const v = tk[k];
  if (!v || !v.cik_str || !v.ticker) continue;
  const cik = Number(v.cik_str);
  const cur = cik2[cik];
  // Preferred shares and warrants share the issuer's CIK (SMCIP next to SMCI),
  // and the common stock is always the shortest ticker for that CIK.
  if (!cur || v.ticker.length < cur.ticker.length) cik2[cik] = { ticker: v.ticker, title: v.title || '' };
}
const before = {};
for (const r of prev) if (r && r.cik != null) before[r.cik] = Number(r.val);

const floorUsd = Math.max(0, Number(ctx.min_quarterly_revenue_musd || 200)) * 1e6;
const cap = Number(ctx.max_growth_pct || 300);

const rows = [];
for (const r of cur) {
  if (!r || r.cik == null) continue;
  const rev = Number(r.val);
  if (!isFinite(rev) || rev < floorUsd) continue;
  const p = before[r.cik];
  if (!isFinite(p) || p <= 0) continue;
  const t = cik2[r.cik];
  if (!t) continue;                        // no listed ticker, not investable here
  if (/[-.]W?[SR]?$/i.test(t.ticker) && t.ticker.length > 5) continue;  // warrant and rights lines
  const growth = ((rev - p) / p) * 100;
  if (growth > cap) continue;              // acquisition and restructuring artefacts
  rows.push({ ticker: t.ticker, name: (r.entityName || t.title || '').slice(0, 48),
              revenue_usd: rev, revenue_prior_usd: p, growth_pct: Math.round(growth * 10) / 10 });
}

const sort = String(ctx.sort || 'growth');
if (sort === 'scale') rows.sort((a, b) => b.revenue_usd - a.revenue_usd);
else rows.sort((a, b) => b.growth_pct - a.growth_pct);

const want = Math.min(12, Math.max(5, Number(ctx.count || 8)));
// Take a wider slice than needed so the price step and the model both have room.
const shortlist = rows.slice(0, Math.min(20, Math.max(want * 2, 12)));  // Yahoo spark caps at 20 symbols
if (!shortlist.length) {
  return [{ json: { ...ctx, universe: rows.length, empty: true, symbols: '', meta: [] } }];
}
return [{ json: { ...ctx, universe: rows.length, empty: false, want,
  symbols: shortlist.map(r => r.ticker).join(','), meta: shortlist } }];

const j = $input.first().json;
const de = j.language === 'de';
return [{ json: { chat_id: j.chat_id, text: de
  ? '🔎 Der Screen hat mit diesen Kriterien nichts gefunden. Versuch eine niedrigere Umsatzschwelle oder eine breitere Formulierung.'
  : '🔎 The screen returned nothing with those criteria. Try a lower revenue floor or a broader request.' } }];

const ctx = $('Build Candidates').first().json;
if (ctx.empty) return [{ json: { ...ctx, picks: [] } }];
const sp = $input.first().json.spark || {};
if (sp.error) throw new Error('Yahoo spark rejected the request: ' + (sp.error.description || sp.error.code));
const res = sp.result || $input.first().json.spark || [];
const arr = Array.isArray(res) ? res : [];
const px = {};
for (const r of arr) {
  const sym = r.symbol || (r.response && r.response[0] && r.response[0].meta && r.response[0].meta.symbol);
  const resp = (r.response && r.response[0]) || r;
  const meta = resp && resp.meta;
  // Yahoo moved the close series into indicators.quote[0].close. Reading resp.close
  // returned [] silently, which left day_pct and week_pct null on every name and
  // made the momentum sort rank everything as -999. Old path kept as a fallback.
  const ind = resp && resp.indicators && resp.indicators.quote && resp.indicators.quote[0];
  const closes = ((ind && ind.close) || (resp && resp.close) || []).filter(v => typeof v === 'number');
  if (!sym || !meta) continue;
  const last = typeof meta.regularMarketPrice === 'number' ? meta.regularMarketPrice : closes[closes.length - 1];
  // A true one-day move is vs the PREVIOUS BAR's close. meta.chartPreviousClose is
  // the close preceding the whole requested range, which is a different number.
  const prevBar = closes.length >= 2 ? closes[closes.length - 2] : null;
  const metaDay = typeof meta.regularMarketChangePercent === 'number' ? meta.regularMarketChangePercent : null;
  px[String(sym).toUpperCase()] = {
    price: last, currency: meta.currency || 'USD',
    day_pct: (last != null && prevBar) ? Math.round(((last - prevBar) / prevBar) * 1000) / 10
           : (metaDay != null ? Math.round(metaDay * 10) / 10 : null),
    week_pct: (closes.length >= 2 && closes[0]) ? Math.round(((last - closes[0]) / closes[0]) * 1000) / 10 : null
  };
}
const picks = ctx.meta.map(m => {
  const q = px[m.ticker.toUpperCase()] || {};
  return { ...m,
    revenue_bn: Math.round(m.revenue_usd / 1e8) / 10,
    price: q.price ?? null, currency: q.currency || '',
    day_pct: q.day_pct ?? null, week_pct: q.week_pct ?? null,
    has_quote: q.price != null };
});
// Momentum sort only makes sense once prices are in.
if (ctx.sort === 'momentum') picks.sort((a, b) => (b.week_pct ?? -999) - (a.week_pct ?? -999));
const withQuote = picks.filter(p => p.has_quote);
const noQuote = picks.filter(p => !p.has_quote).map(p => p.ticker);
return [{ json: { ...ctx, picks: withQuote.slice(0, ctx.want), no_quote: noQuote.slice(0, 8) } }];

const esc = s => String(s == null ? '' : s).replace(/<br\s*\/?>/gi,'\n').replace(/<\/?p>/gi,'\n').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const ctx = $('Assemble Picks').first().json;
const raw = $input.first().json.message?.content ?? $input.first().json;
const noDash = s => typeof s === 'string' ? s.replace(/\s*[—–]\s*/g, ', ').replace(/ {2,}/g,' ') : s;
const deep = v => Array.isArray(v) ? v.map(deep)
  : (v && typeof v === 'object') ? Object.fromEntries(Object.entries(v).map(([k,x]) => [k, deep(x)]))
  : noDash(v);
const r = deep(typeof raw === 'string' ? JSON.parse(raw) : raw);
const de = ctx.language === 'de';
const arr = v => Array.isArray(v) ? v : (v ? [v] : []);

// Rule 28: every number in the header line is formatted here, not written by the
// model. The model used to narrate "revenue up 292.5 percent year on year to 408
// million dollars from 104 million dollars", which is unskimmable. It now only
// supplies the two judgement clauses.
const SYM = { USD: '$', EUR: '€', GBP: '£', CHF: 'CHF ', JPY: '¥' };
const cur = c => SYM[String(c || 'USD').toUpperCase()] || (String(c || '') + ' ');
const pct = n => (n == null || !isFinite(n)) ? '' : (n > 0 ? '+' : '') + Math.round(n) + '%';
const money = u => {
  if (u == null || !isFinite(u)) return '';
  return u >= 1e9 ? '$' + (Math.round(u / 1e8) / 10) + 'B' : '$' + Math.round(u / 1e6) + 'M';
};
const price = p => {
  if (p == null || !isFinite(p)) return '';
  return p >= 100 ? Math.round(p) : Math.round(p * 100) / 100;
};
const move = n => {
  if (n == null || !isFinite(n)) return '';
  const a = Math.round(Math.abs(n) * 10) / 10;
  return (n >= 0 ? '▲' : '▼') + a + '%';
};
// Clause length is capped here as well as in the prompt: a prompt ban needs a
// code backstop or one long sentence undoes the whole layout.
const CLAUSE = 95;
const clip = s => {
  let t = String(s || '').trim().replace(/\s+/g, ' ');
  if (t.length <= CLAUSE) return t;
  t = t.slice(0, CLAUSE);
  const sp = t.lastIndexOf(' ');
  if (sp > CLAUSE * 0.6) t = t.slice(0, sp);
  return t.replace(/[.,;:]$/, '') + '…';
};

const byTicker = {};
for (const p of arr(ctx.picks)) byTicker[String(p.ticker).toUpperCase()] = p;

const L = [];
L.push(de ? '🔎 <b>Screening-Ergebnis</b>' : '🔎 <b>Screen results</b>');
if (ctx.headline) L.push('<i>' + esc(ctx.headline) + '</i>');
L.push('<i>' + (de ? '% = Umsatz gegenueber Vorjahresquartal. Danach Quartalsumsatz, Kurs, 5-Tage-Bewegung.'
                   : '% = revenue vs the same quarter last year. Then quarterly revenue, price, 5 day move.') + '</i>');
L.push('');
if (r.overview) { L.push(esc(r.overview)); L.push(''); }

for (const n of arr(r.names)) {
  const p = byTicker[String(n.ticker).toUpperCase()] || {};
  const bits = [];
  const g = pct(p.growth_pct);
  const rev = money(p.revenue_usd);
  if (rev) bits.push(rev);
  const pr = price(p.price);
  if (pr !== '') bits.push(cur(p.currency) + pr);
  const wk = move(p.week_pct);
  if (wk) bits.push(wk + ' 5d');
  // ticker and the growth figure carry the skim, so they are the only bold text
  L.push('<b>' + esc(n.ticker) + (g ? '  ' + g : '') + '</b>' + (bits.length ? '  ' + esc(bits.join('  ·  ')) : ''));
  if (n.name || p.name) L.push(esc(String(n.name || p.name).slice(0, 44)));
  if (n.for) L.push('➕ ' + esc(clip(n.for)));
  if (n.against) L.push('➖ ' + esc(clip(n.against)));
  L.push('');
}

const w = arr(r.watch);
if (w.length) {
  L.push(de ? '<b>Vorher pruefen</b>' : '<b>Check before acting</b>');
  for (const b of w) L.push('• ' + esc(clip(b)));
  L.push('');
}
if (ctx.notes) L.push('<i>' + esc(ctx.notes) + '</i>');
if (r.caveat) L.push('<i>' + esc(r.caveat) + '</i>');
if (arr(ctx.no_quote).length) {
  L.push('<i>' + (de ? 'Kein Kurs verfuegbar fuer: ' : 'No price data for: ') + esc(arr(ctx.no_quote).join(', ')) + '</i>');
}

let text = L.join('\n').replace(/\n{3,}/g, '\n\n').trim();
// A blank send is a 400 from Telegram, so never let an empty brief through.
if (!text || !arr(r.names).length) {
  text = (de ? '🔎 Der Screen lief, aber es kam keine belastbare Auswahl zurueck. Versuch es mit einer breiteren Formulierung.'
             : '🔎 The screen ran but produced no usable shortlist. Try a broader request.');
}
const MAX = 3800;
if (text.length > MAX) {
  text = text.slice(0, MAX);
  const lo = text.lastIndexOf('<');
  if (lo > text.lastIndexOf('>')) text = text.slice(0, lo);
  for (const t of ['b','i']) {
    const o = (text.match(new RegExp('<' + t + '>', 'g')) || []).length;
    const c = (text.match(new RegExp('</' + t + '>', 'g')) || []).length;
    for (let k = 0; k < o - c; k++) text += '</' + t + '>';
  }
  text += '\n…(truncated)';
}

// ---------------------------------------------------------------------------
// Full detail as a .txt attachment. The Telegram message is deliberately short
// enough to skim, so everything that got clipped or cut from the shortlist lives
// here instead. Same mechanism as linkedin_gigs: build the binary in this node,
// then pick it back up after the send (a Telegram node does not pass input through).
// ---------------------------------------------------------------------------
const pad = (s, n) => String(s == null ? '' : s).padEnd(n);
// integer percent is right for a 296% revenue jump, wrong for a 7.8% price move
const pct1 = n => (n == null || !isFinite(n)) ? '-' : (n > 0 ? '+' : '') + (Math.round(n * 10) / 10) + '%';
// Build Candidates rebuilds ctx from Prep Screen Input and Parse Criteria, so the
// frame strings never arrive in ctx. Read them off Pick Frames itself.
let fr = ctx.frame_current || '', fp = ctx.frame_prior || '';
try {
  const pf = $('Pick Frames').first().json;
  fr = pf.frame_current || fr;
  fp = pf.frame_prior || fp;
} catch (e) { /* reply path does not run Pick Frames */ }
const today = new Date().toISOString().slice(0, 10);
const T = [];
T.push('SCREEN RESULTS  ' + today);
T.push('='.repeat(72));
T.push('Request     : ' + (ctx.text || ''));
T.push('Sort        : ' + (ctx.sort || '') + '   min quarterly revenue: ' + ctx.min_quarterly_revenue_musd + 'm USD   growth cap: ' + ctx.max_growth_pct + '%');
T.push('SEC frames  : ' + fr + ' vs ' + fp + '  (US filers reporting through SEC XBRL)');
T.push('Universe    : ' + (ctx.universe || 0) + ' filers had comparable revenue in both quarters');
T.push('Shortlisted : ' + arr(ctx.meta).length + '   shown in Telegram: ' + arr(ctx.picks).length);
T.push('');
if (r.overview) { T.push('WHAT THIS SCREEN SELECTED FOR'); T.push(String(r.overview)); T.push(''); }

T.push('-'.repeat(72));
T.push('SHORTLIST, FULL NUMBERS');
T.push('-'.repeat(72));
T.push(pad('TICKER', 9) + pad('GROWTH', 10) + pad('REVENUE', 13) + pad('PRIOR YEAR', 13) + pad('PRICE', 12) + pad('1D', 9) + '5D');
for (const p of arr(ctx.picks)) {
  T.push(pad(p.ticker, 9)
    + pad(pct(p.growth_pct), 10)
    + pad(money(p.revenue_usd), 13)
    + pad(money(p.revenue_prior_usd), 13)
    + pad((p.price != null ? cur(p.currency) + price(p.price) : 'n/a'), 12)
    + pad(pct1(p.day_pct), 9)
    + pct1(p.week_pct));
}
T.push('');

// Names the screen found but the shortlist cut, so he can see what was just below the line.
const shown = new Set(arr(ctx.picks).map(p => String(p.ticker).toUpperCase()));
const cut = arr(ctx.meta).filter(m => !shown.has(String(m.ticker).toUpperCase()));
if (cut.length) {
  T.push('-'.repeat(72));
  T.push('ALSO MATCHED, NOT SHOWN (' + cut.length + ')');
  T.push('-'.repeat(72));
  for (const m of cut) {
    T.push(pad(m.ticker, 9) + pad(pct(m.growth_pct), 10) + pad(money(m.revenue_usd), 13)
      + pad(money(m.revenue_prior_usd), 13) + String(m.name || '').slice(0, 40));
  }
  T.push('');
}

T.push('-'.repeat(72));
T.push('THE CASE EACH WAY, IN FULL');
T.push('-'.repeat(72));
for (const n of arr(r.names)) {
  const p = byTicker[String(n.ticker).toUpperCase()] || {};
  T.push(String(n.ticker) + '  ' + String(n.name || p.name || ''));
  T.push('  ' + pct(p.growth_pct) + ' revenue year on year, ' + money(p.revenue_usd)
    + ' this quarter vs ' + money(p.revenue_prior_usd) + ' a year earlier'
    + (p.price != null ? ', share price ' + cur(p.currency) + price(p.price) : ''));
  // untruncated here, unlike the Telegram message
  if (n.for) T.push('  FOR     : ' + String(n.for));
  if (n.against) T.push('  AGAINST : ' + String(n.against));
  T.push('');
}

const wl = arr(r.watch);
if (wl.length) {
  T.push('-'.repeat(72));
  T.push('CHECK BEFORE ACTING');
  T.push('-'.repeat(72));
  for (const b of wl) T.push('  - ' + String(b));
  T.push('');
}
if (arr(ctx.no_quote).length) T.push('No price data for: ' + arr(ctx.no_quote).join(', '));
if (r.caveat) T.push(String(r.caveat));
T.push('');
T.push('This is a screen, not advice. Revenue figures come straight from SEC XBRL');
T.push('company filings; prices come from Yahoo. Nothing here has been checked for');
T.push('margins, debt, dilution or valuation.');

const fileName = 'screen_' + (fr || today) + '_' + today + '.txt';
const binary = await this.helpers.prepareBinaryData(Buffer.from(T.join('\n'), 'utf-8'), fileName, 'text/plain');

return [{ json: { chat_id: ctx.chat_id, language: ctx.language, text,
  log_criteria: ctx.sort + ' | min ' + ctx.min_quarterly_revenue_musd + 'm | cap ' + ctx.max_growth_pct + '%',
  log_universe: String(ctx.universe || 0),
  log_candidates: arr(r.names).map(n => n.ticker).join(', '),
  preview: text.replace(/<[^>]+>/g,'').slice(0,300),
  file_name: fileName,
  caption: (de ? 'Alle Zahlen und die vollstaendige Begruendung' : 'Full numbers and the complete reasoning')
}, binary: { data: binary } }];

// A Telegram node outputs the API response, not its input (rule 18), so the file
// has to be picked back up from Build Message. No file means nothing to attach.
const b = $('Build Message').first();
if (!b || !b.json.file_name || !b.binary) return [];
return [{ json: b.json, binary: b.binary }];
